import{_ as o,o as t,c as s,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-25（地球科学 / 古气候 / 劳伦泰德冰盖再扩张）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-10-25-earth.md","filePath":"topics/earth-science/science-daily-2026-10-25-earth.md"}'),n={name:"topics/earth-science/science-daily-2026-10-25-earth.md"};function c(i,e,a,l,d,g){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="科学日报-·-2026-10-25-地球科学-古气候-劳伦泰德冰盖再扩张" tabindex="-1">科学日报 · 2026-10-25（地球科学 / 古气候 / 劳伦泰德冰盖再扩张） <a class="header-anchor" href="#科学日报-·-2026-10-25-地球科学-古气候-劳伦泰德冰盖再扩张" aria-label="Permalink to &quot;科学日报 · 2026-10-25（地球科学 / 古气候 / 劳伦泰德冰盖再扩张）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> — 第44期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-earth</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-25-下一次冰期其实「已经开始」-却被人类升温叫停" tabindex="-1">科学日报 2026-10-25：下一次冰期其实「已经开始」，却被人类升温叫停 <a class="header-anchor" href="#科学日报-2026-10-25-下一次冰期其实「已经开始」-却被人类升温叫停" aria-label="Permalink to &quot;科学日报 2026-10-25：下一次冰期其实「已经开始」，却被人类升温叫停&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ DOI: 10.1126/science.aed3379</p></blockquote><ul><li>背景机制：冰期—间冰期旋回中，更新世最大的冰盖——<strong>劳伦泰德冰盖（LIS, Laurentide Ice Sheet）</strong>——在间冰期退缩到<strong>北极加拿大</strong>、达到<strong>最小规模</strong>；其后的「<strong>再扩张</strong>」按定义<strong>标志着下一次冰期的开始</strong>。也就是说，<strong>「下一次冰期何时开始」在地质记录里是可读的</strong>。</li><li>本篇的结论（把边界条件钉到具体年份）： <ul><li>最近一次 LIS 的<strong>最后残骸</strong> = <strong>加拿大巴芬岛的 Barnes 冰帽</strong>；</li><li><strong>约 3600 年前</strong>达<strong>间冰期最小规模</strong>；</li><li><strong>约 2000 年前开始再扩张</strong> → <strong>下一次冰期实际已经启动</strong>；</li><li>这个<strong>新生 LIS 在约 1960 年达到最大规模</strong>；此后<strong>人为夏季升温</strong>使<strong>质量平衡转负、冰缘退缩</strong> → <strong>下一次冰期被终止</strong>。</li></ul></li><li>核心论点：在<strong>夏季日照量持续下降</strong>（本该继续降温、推进冰期）的背景下，冰期却被终结 → <strong>恰好说明异常温室气体强迫的影响之大</strong>。</li><li>洞察（对本库 <code>earth-science</code> × 方法论）： <ol><li><strong>这是「地质时钟」与「人类世扰动」直接对照的罕见案例</strong>。地球轨道强迫的时间尺度是 <strong>10⁴–10⁵ 年</strong>、幅度可预测；人类强迫的时间尺度是 <strong>10¹ 年</strong>、幅度<strong>压过了正在下行的辐射强迫</strong>。<strong>结论不是「冰期取消了」这类口号，而是一个可检验的定量对照</strong>：轨道强迫的符号（降）与观测结果（升）相反，唯一的候选解释是温室气体。</li><li>与本库同族条目串成一条主线：<code>topics/earth-science/science-daily-2026-10-20.md</code>（15,330 个冰崖激光测高约束<strong>海洋冰崖不稳定性</strong>）、<code>topics/earth-science/science-daily-2026-10-24-earth.md</code>（深部生物圈/产甲烷）。共同教益是：<strong>「地球系统的『默认轨迹』可以被外部强迫改写」</strong> —— 要么是冰盖动力学的非线性（冰崖崩解），要么是碳循环（产甲烷/温室气体）。</li><li>可迁移判据：<strong>判断「是否被人为改写」最硬的证据，是指出「系统本该往 A 走，却走了 B」</strong>（这里：辐射强迫降 → 冰期该推进 → 实际终止）。这比「变暖了多少度」更能锁定人为原因，因为<strong>它用到了系统的内部参照系（轨道时钟）</strong>。迁移到外脑：<strong>当你怀疑某个结果被外部因素污染时，先找出这个系统「自己本该走的方向」，再比对实际方向是否相反。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ 第44期 科学板块</p></blockquote><p>关键词：劳伦泰德冰盖、LIS、间冰期最小规模、再扩张标志下一次冰期开始、Barnes 冰帽、巴芬岛、约 3600 年前达最小、约 2000 年前再扩张、约 1960 年达最大、人为夏季升温、质量平衡转负、冰缘退缩、冰期被终止、夏季日照下降却升温、温室气体强迫、轨道时钟作内部参照系、本该往 A 走却走 B</p><p>关联：<code>topics/earth-science/science-daily-2026-10-20.md</code>（冰崖不稳定性）、<code>topics/earth-science/science-daily-2026-10-24-earth.md</code>（深部生物圈产甲烷）、<code>topics/physics/cosmic-inflation-origin.md</code>（时间尺度与可证伪性）、<code>topics/earth-science/index.md</code></p>',10)])])}const u=o(n,[["render",c]]);export{p as __pageData,u as default};
